const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const menu=$('.menu-toggle'),nav=$('#nav');menu?.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',open);nav.classList.toggle('open',open);document.body.classList.toggle('locked',open);menu.firstChild.textContent=open?'Close ':'Menu ';});document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(nav?.classList.contains('open'))menu.click();$$('.nav-drop[open]').forEach(d=>d.open=false);}});document.addEventListener('click',e=>{$$('.nav-drop[open]').forEach(d=>{if(!d.contains(e.target))d.open=false;});});
function scrollState(){document.body.classList.toggle('scrolled',scrollY>550)}addEventListener('scroll',scrollState,{passive:true});scrollState();
if($('[data-service]'))fetch('/services.json').then(r=>r.json()).then(services=>{$$('[data-service]').forEach(b=>b.addEventListener('click',()=>{const s=services.find(s=>s[0]===b.dataset.service);$$('[data-service]').forEach(x=>x.setAttribute('aria-pressed',x===b));$('.service-image').src='/assets/source-'+s[4]+'.jpeg';$('.service-image').alt=s[1]+' photograph from the original company website';$('#service-description').textContent=s[3];$('#service-link').href='/services/'+s[0]+'/';$('#service-link').textContent='Explore '+s[1].toLowerCase();}));}).catch(()=>{});
if($('[data-review]'))fetch('/reviews.json').then(r=>r.json()).then(reviews=>{$$('[data-review]').forEach(b=>b.addEventListener('click',()=>{const r=reviews[+b.dataset.review];$('#review-quote').textContent='“'+r[2]+'”';$('#review-name').textContent=r[0];$('#review-role').textContent=r[1];$$('[data-review]').forEach(x=>x.setAttribute('aria-pressed',x===b));}));}).catch(()=>{});
$$('[data-filter]').forEach(b=>b.addEventListener('click',()=>{$$('[data-filter]').forEach(x=>x.setAttribute('aria-pressed',x===b));$$('[data-project]').forEach(p=>p.hidden=b.dataset.filter!=='All'&&p.dataset.type!==b.dataset.filter);}));
let category='All';function filterFaq(){const term=$('#faq-search')?.value.toLowerCase()||'';let count=0;$$('#all-faqs .faq').forEach(d=>{d.hidden=(category!=='All'&&d.dataset.category!==category)||!d.textContent.toLowerCase().includes(term);if(!d.hidden)count++;});if($('#no-faqs'))$('#no-faqs').hidden=count!==0;}$('#faq-search')?.addEventListener('input',filterFaq);$$('[data-faq-filter]').forEach(b=>b.addEventListener('click',()=>{category=b.dataset.faqFilter;$$('[data-faq-filter]').forEach(x=>x.setAttribute('aria-pressed',x===b));filterFaq();}));
$('#quote-form')?.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target);const text=['Roofing quote request',...['name','phone','email','location','service','property','description','contact'].map(k=>k+': '+f.get(k))].join('\n');const box=$('#form-result');box.replaceChildren();const p=document.createElement('p');p.textContent='Summary prepared on your device. Nothing has been sent.\n\n'+text;const a=document.createElement('a');a.href='tel:+17723563443';a.textContent='Call Near Shore Roofing';box.append(p,a);box.focus();});
